select amount_bucket, merchant, unique_accounts from (select case when amount >= 4100 then 'high' when amount >= 1700 then 'mid' else 'low' end as amount_bucket, merchant, count(distinct amount) as unique_accounts from transactions group by case when amount >= 4100 then 'high' when amount >= 1700 then 'mid' else 'low' end, merchant) as sub where unique_accounts >= 5 order by merchant, unique_accounts desc
